        Cat 一只 = new Cat("{n1}", {c1});

        一只.start();

        int 本喵的数 = 0;
        for (int i = 0; i < {c3}; i++) {
            本喵的数 = 本喵的数 + 1;
        }

        一只.join();

        System.out.println("{n1}数到：" + 一只.数到 + " 条");
        System.out.println("本喵数到：" + 本喵的数 + " 条");
